"""Load the Sanskrit text and produce what each screen shows. Transliteration is generated by code from the Devanagari (nothing is typed in)."""
import json
import re
from functools import lru_cache
from pathlib import Path

from indic_transliteration import sanscript

DATA = Path(__file__).parent / "data" / "gita_sanskrit.json"
DEVANAGARI_DIGITS = str.maketrans("0123456789", "०१२३४५६७८९")


@lru_cache(maxsize=1)
def chapters():
    return json.loads(DATA.read_text(encoding="utf-8"))["chapters"]


def iast(text):
    """Devanagari to IAST (the scholarly Latin transliteration). Danda marks become | and ||."""
    return sanscript.transliterate(text, sanscript.DEVANAGARI, sanscript.IAST).replace("।", "|").replace("॥", "||")


def verse_screens(verse):
    """What the two screens of one verse show, as plain strings: ``{'sanskrit': (top, lines), 'iast': (top, lines)}``.

    top is the reference (and speaker, when the source names one); lines are the verse lines with the closing double danda restored
    on the last line (the source's reference marker replaced it)."""
    ref = f"{verse['chapter']}.{verse['verse']}"
    lines = [re.sub(r"।(?=\S)", "। ", line) for line in verse["lines"]]      # the source sometimes joins two half-verses after a danda; let them wrap
    lines[-1] = lines[-1].rstrip("।") + " ॥"
    speaker = verse["speaker"]
    sk_top = ref.translate(DEVANAGARI_DIGITS) + ("  " + speaker if speaker else "")
    la_top = ref + ("  ·  " + iast(speaker) if speaker else "")
    return {"sanskrit": (sk_top, lines), "iast": (la_top, [iast(line) for line in lines])}


def reading_frames(lines, fps=10, minimum=4.0, per_char=0.10, maximum=18.0):
    """How many frames a screen stays up: longer verses stay longer (a fixed, documented rule, not a recitation timing)."""
    chars = sum(len(line) for line in lines)
    return int(round(min(maximum, max(minimum, per_char * chars)) * fps))
